<script setup lang="tsx">
import { onMounted, ref, computed } from "vue";
import { useRouter } from "vue-router";
import type { BaseTableCol, TableRowData } from "tdesign-vue-next";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, ShowErrorTips, ShowTextTipsSuccess } from "@/util/tips";
import { GetBotGameList, GetBotAgentList, ParseBotGame, ParseBotAgent, PostBotGameCreateMatch } from "@/apis/bot";
import { GetAvatarUrl } from "@/util/avatar";
import { handleGotoBotMatch, handleOpenUsername } from "@/util/router";
import type { BotAgent, BotAgentView, BotGame, BotGameView } from "@/types/bot";
import type { CellParams } from "@/types/table";
import { useBreakpoint } from "@/composables/useBreakpoint";

const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

// 游戏列表和选择
const gameList = ref<BotGameView[]>([]);
const selectedGame = ref<string | null>(null);

// 加载状态
const dataLoading = ref(true);
const gamesLoading = ref(true);
const creatingMatch = ref(false);

const showAgentDialog = ref(false);
let currentSelectAgentIndex = -1;
const agentLoading = ref(true);
const agentList = ref<BotAgentView[]>([]);

// 游戏信息
const gameInfo = computed(() => {
  return gameList.value.find(game => game.gameKey === selectedGame.value) || null;
});

// 游戏最小人数
const minPlayers = computed(() => {
  return gameInfo.value?.playerMin || 2;
});

// 游戏最大人数
const maxPlayers = computed(() => {
  return gameInfo.value?.playerMax || 2;
});

// 空格列表
const playerSlots = ref([] as { index: number; isRequired: boolean; isLoading: boolean, agent: BotAgentView | null }[])

const handleSelectAgent = (agentId: number) => {
  playerSlots.value[currentSelectAgentIndex].agent = agentList.value.find(agent => agent.id === agentId) || null;
  showAgentDialog.value = false;
}

const agentColumns: BaseTableCol<TableRowData>[] = [
  {
    title: "ID",
    colKey: "id",
  },
  {
    title: "名称",
    colKey: "name",
  },
  {
    title: "版本",
    colKey: "version",
  },
  {
    title: "作者",
    colKey: "inserter",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const avatarUrl = GetAvatarUrl(data.row.inserterUsername, data.row.inserterEmail);
      return (
        <t-space>
          <t-avatar shape="round" size="32px" image={avatarUrl} hide-on-load-failed={false} />
          <t-button variant="text" onClick={() => handleOpenUsername(router, data.row.inserterUsername)}>
            {data.row.inserterNickname}
          </t-button>
        </t-space>
      );
    },
  },
  {
    title: "操作",
    colKey: "action",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-space>
          <t-button theme="default" onClick={() => handleSelectAgent(data.row.id)}>
            选择
          </t-button>
        </t-space>
      );
    }
  }
];

// 检查是否可以创建对局
const canCreateMatch = computed(() => {
  return selectedGame.value;
});

const onGameChange = () => {
  playerSlots.value = []
  if (gameInfo.value) {
    for (let i = 1; i <= maxPlayers.value; i++) {
      playerSlots.value.push({
        index: i,
        isRequired: false,
        isLoading: false,
        agent: null
      });
    }
  }
}

// 加载游戏列表
const fetchGameList = async () => {
  dataLoading.value = true;
  try {
    const response = await GetBotGameList();
    gameList.value = response.data.map((item: BotGame) => ParseBotGame(item));
    // 优先选择URL中指定的game_key
    const urlParams = new URLSearchParams(window.location.search);
    const gameKeyFromUrl = urlParams.get('game_key');
    if (gameKeyFromUrl && gameList.value.some(game => game.gameKey === gameKeyFromUrl)) {
      selectedGame.value = gameKeyFromUrl;
    } else if (gameList.value.length > 0) {
      selectedGame.value = gameList.value[0].gameKey;
    }
    onGameChange();
  } catch (err) {
    console.error('获取游戏列表失败:', err);
    ShowErrorTips(globalProperties, GetCommonErrorCode());
  } finally {
    gamesLoading.value = false;
    dataLoading.value = false;
  }
};

const fetchAgentList = async () => {
  agentLoading.value = true;

  try {
    const response = await GetBotAgentList(Number(searchForm.value.Id), searchForm.value.name, gameInfo.value?.gameKey, searchForm.value.username);
    if (response.code !== 0) {
      ShowErrorTips(globalProperties, response.code);
      return;
    }

    agentList.value = []

    if (response.data && response.data.list) {
      agentList.value = response.data.list.map((item: BotAgent) => ParseBotAgent(item));
    }
  } finally {
    agentLoading.value = false;
  }

}

const openAgentDialog = async (slotIndex: number) => {
  currentSelectAgentIndex = slotIndex;
  playerSlots.value[currentSelectAgentIndex].isLoading = true;
  await fetchAgentList()
  playerSlots.value[currentSelectAgentIndex].isLoading = false;
  showAgentDialog.value = true;
};

const searchForm = ref({
  Id: "",
  username: "",
  name: "",
});

const handleSearchFormSubmit = async (_form: unknown) => {
  await fetchAgentList();
};

const handleSearchFormReset = async () => {
  searchForm.value.Id = "";
  searchForm.value.username = "";
  searchForm.value.name = "";
  await fetchAgentList();
};

// 清除选择的 选手
const clearSelectedAgent = () => {
  playerSlots.value[currentSelectAgentIndex].agent = null;
  showAgentDialog.value = false;
}

const handleGotoList = () => {
  const routeData = router.resolve({ name: 'bot-agent-list' });
  window.open(routeData.href, "_blank");
}

// 创建对局
const handleCreateMatch = async () => {
  // 验证是否选择了Agent
  const selectedAgents = playerSlots.value.filter(slot => slot.agent !== null);
  if (selectedAgents.length === 0) {
    globalProperties.$message.warning(`至少需要选择 1 个Agent`);
    return;
  }

  // 收集 agent ID
  const agentIds = selectedAgents.map(slot => slot.agent!.id);

  try {
    creatingMatch.value = true;
    const response = await PostBotGameCreateMatch(selectedGame.value!, agentIds);
    if (response.code === 0) {
      ShowTextTipsSuccess(globalProperties, '对局创建成功');
      // 获取返回的 matchid
      const matchId = response.data;
      // 跳转到对局页面
      handleGotoBotMatch(selectedGame.value!, matchId);
    } else {
      ShowErrorTips(globalProperties, response.code);
    }
  } catch (err) {
    console.error('创建对局失败:', err);
    ShowErrorTips(globalProperties, GetCommonErrorCode());
  } finally {
    creatingMatch.value = false;
  }
};

// 初始化数据
onMounted(() => {
  fetchGameList();
});

</script>

<template>
  <t-card style="margin: 10px;">
    <template #header>
      <div style="display: flex; justify-content: space-between; align-items: center;">
        <span>创建对局</span>
      </div>
    </template>

    <div v-if="dataLoading" class="loading-container">
      <!-- t-skeleton 没有 rows 属性，需用 row-col 显式描述每一行 -->
      <t-skeleton
        :row-col="[
          { width: '30%', height: '28px' },
          [{ width: '100%', height: '40px' }],
          [{ width: '100%', height: '40px' }],
          [{ width: '100%', height: '40px' }],
          [{ width: '100%', height: '120px' }],
          [{ width: '180px', height: '40px' }],
        ]"
        animation="gradient"
      />
    </div>

    <div v-else class="create-match-container">
      <!-- 游戏选择 -->
      <div class="form-section">
        <h3>选择游戏</h3>
        <t-select
v-model="selectedGame" placeholder="请选择游戏" :disabled="gamesLoading" :style="{ width: isMobile ? '100%' : '300px' }"
          @change="onGameChange">
          <t-option v-for="game in gameList" :key="game.gameKey" :label="game.title" :value="game.gameKey">
            {{ game.title }}
          </t-option>
        </t-select>
      </div>

      <!-- 游戏信息展示 -->
      <div v-if="gameInfo" class="form-section game-info">
        <h3>游戏信息</h3>
        <div class="info-item">
          <span class="label">游戏名称：</span>
          <span>{{ gameInfo.title }}</span>
        </div>
        <div class="info-item">
          <span class="label">游戏描述：</span>
          <span>{{ gameInfo.introduction }}</span>
        </div>
        <div class="info-item">
          <span class="label">最小人数：</span>
          <span>{{ minPlayers }}</span>
        </div>
        <div class="info-item">
          <span class="label">最大人数：</span>
          <span>{{ maxPlayers }}</span>
        </div>
      </div>

      <!-- 空格选择 -->
      <div class="form-section">
        <h3>玩家分配 (最少 {{ minPlayers }} 人，最多 {{ maxPlayers }} 人)</h3>
        <p>如果仅选择一个自己的选手，其他位置留空，则系统会匹配同水平选手并计算排位积分</p>
        <p>其他情况下，则仅开启对局而不会计算排位积分</p>
        <div class="slot-container">
          <div
v-for="(slot, index) in playerSlots" :key="slot.index" class="player-slot"
            :class="{ 'required': slot.isRequired }">
            <div class="slot-header">
              <span class="slot-index">玩家 {{ slot.index }}</span>
            </div>
            <div class="slot-content">
              <t-button block variant="dashed" :loading="slot.isLoading" @click="openAgentDialog(index)">
                <template v-if="slot.agent">
                  {{ slot.agent.name }}
                </template>
                <template v-else>
                  选择选手
                </template>
              </t-button>
            </div>
          </div>
        </div>
      </div>

      <!-- 创建按钮 -->
      <div class="form-section">
        <t-button theme="primary" :disabled="!canCreateMatch" :loading="creatingMatch" @click="handleCreateMatch">
          创建对局
        </t-button>
        <t-button variant="outline" style="margin-left: 10px;" @click="router.go(-1)">
          返回
        </t-button>
      </div>
    </div>
  </t-card>

  <t-dialog v-model:visible="showAgentDialog" :footer="false" :width="isMobile ? '90vw' : '1300px'">
    <template #header>
      <div style="display: flex; justify-content: space-between; align-items: center; width: 100%;">
        <span style="font-size: 18px; font-weight: bold;">{{ gameInfo?.title }}</span>
        <t-button @click="handleGotoList">
          查看选手列表
        </t-button>
      </div>
    </template>
    <t-form :layout="isMobile ? 'vertical' : 'inline'" @submit="handleSearchFormSubmit" @reset="handleSearchFormReset">
      <t-form-item label="ID">
        <t-input v-model="searchForm.Id" placeholder="请输入Agent ID" />
      </t-form-item>
      <t-form-item label="名称">
        <t-input v-model="searchForm.name" placeholder="请输入Agent名称" />
      </t-form-item>
      <t-form-item label="作者">
        <t-input v-model="searchForm.username" placeholder="仅支持输入完整用户名" />
      </t-form-item>
      <t-form-item>
        <t-space>
          <t-button theme="primary" type="submit">搜索</t-button>
          <t-button theme="default" variant="base" type="reset">重置</t-button>
          <t-button theme="danger" @click="clearSelectedAgent">清除</t-button>
        </t-space>
      </t-form-item>
    </t-form>
    <div class="agent-table-wrapper">
      <t-table :columns="agentColumns" :data="agentList" row-key="id" :loading="agentLoading"></t-table>
    </div>
  </t-dialog>
</template>

